/* ---------- T1: Instandhaltung & Wartung ---------- */
const ihBand=(y,mtbf,mttr,W,lab)=>{const x0=40,x1=440,sc=(x1-x0)/W;let s='',t=0,g=0;
 while(t<W&&g<200){const a=Math.min(mtbf,W-t);s+=RC(x0+t*sc,y,a*sc,26,'color-mix(in srgb,var(--ok) 55%,var(--card))','none',0,0);t+=a;if(t>=W)break;const b=Math.min(mttr,W-t);s+=RC(x0+t*sc,y,Math.max(2,b*sc),26,'var(--red)','none',0,0);t+=b;g++}
 return s+`<rect x="${x0}" y="${y}" width="${x1-x0}" height="26" fill="none" stroke="var(--ink)" stroke-width="1.4"/>`+(lab?L(x0,y-8,lab,'start',15,'var(--ink)',600):'')};
const ihSkizze=k=>{let s=ihBand(70,190,10,600,'600 Betriebsstunden einer Maschine');const sc=400/600;
 s+=BRK(40+0*sc,0,0,'')+`<path d="M40 112H${F(40+190*sc)}" stroke="var(--ok)" stroke-width="2.4"/><path d="M40 106v12M${F(40+190*sc)} 106v12" stroke="var(--ok)" stroke-width="2.4"/>`+L(40+95*sc,134,'MTBF','middle',17,'var(--ok)',700)+L(40+95*sc,152,'läuft','middle',14,'var(--mute)',500);
 s+=`<path d="M${F(40+190*sc)} 62L${F(40+226*sc)} 40" stroke="var(--red)" stroke-width="1.4"/>`+L(40+230*sc,40,'MTTR: Reparatur','start',15,'var(--red)',700);
 s+=RC(60,186,360,64,'color-mix(in srgb,var(--acc) 10%,var(--card))','var(--acc)',12,2)+FORM(240,224,['V = ',{n:'MTBF',d:'MTBF + MTTR'},' = ',{n:'190 h',d:'190 h + 10 h'},' = 95 %'],'middle','einf',17);return s};
