/* ---------- T1: Zerspanung: Fräsen & Schleifen ---------- */
function fraesen(o){const d=o.d||80,w=d*.9,cx=o.cx||200,yt=150,ap=o.ap||8,z=o.z||6,id=o.id||'fr';
 let s=`<defs>${GR(id+'w',STEEL,STEEL2,1)}${GR(id+'s','#5b6472','#aab3c0',0)}</defs>`;
 s+=`<rect x="40" y="${yt}" width="${F(cx-40)}" height="62" fill="url(#${id}w)" stroke="var(--ink)" stroke-width="1.4"/><rect x="${F(cx)}" y="${yt-ap}" width="${F(440-cx)}" height="${62+ap}" fill="url(#${id}w)" stroke="var(--ink)" stroke-width="1.4"/>`;
 s+=RC(30,212,420,18,'color-mix(in srgb,var(--mute) 45%,var(--card))','var(--ink)',3,1.4);
 s+=`<rect x="${F(cx-16)}" y="40" width="32" height="${F(yt-ap-40-34)}" fill="url(#${id}s)" stroke="var(--ink)" stroke-width="1.4"/>`;
 s+=`<rect x="${F(cx-w/2)}" y="${F(yt-ap-34)}" width="${F(w)}" height="34" rx="4" fill="#3a4250" stroke="var(--ink)" stroke-width="1.4"/>`;
 const nv=Math.max(2,Math.round(z/2));for(let i=0;i<nv;i++){const x=cx-w/2+8+(w-16)*(i+.5)/nv;s+=`<path d="M${F(x-7)} ${F(yt-ap-2)}h14l-3 ${F(ap+2)}h-8z" fill="#d4a017" stroke="var(--ink)" stroke-width="1.1"/>`}
 return s}
const frSkizze=k=>{let s=fraesen({id:'fsk',d:90,cx:220,ap:10,z:6});
 s+=AW(140,250,80,250,'var(--flow)')+L(146,256,SUB('v_f'),'start',17,'var(--flow)',700)+L(178,256,'Tisch fährt','start',13,'var(--mute)',500);
 s+=`<path d="M246 56a22 8 0 1 1 -10 -6" fill="none" stroke="var(--red)" stroke-width="2.4"/>`+AW(240,50,232,49,'var(--red)')+L(276,62,'n','start',18,'var(--red)',700);
 s+=`<path d="M${F(220-40.5)} 92H${F(220+40.5)}" stroke="var(--ink)" stroke-width="1.2"/>`+AW(220,92,180,92,'var(--ink)',1.2)+AW(220,92,260,92,'var(--ink)',1.2)+L(220,86,'d','middle',17,'var(--ink)',700);
 s+=`<path d="M260 140H330M260 150H330" stroke="var(--ink)" stroke-width="1" stroke-dasharray="3 3"/>`+AW(320,126,320,139,'var(--ink)',1.2)+AW(320,164,320,151,'var(--ink)',1.2)+L(330,162,SUB('a_p'),'start',17,'var(--ink)',700);
 return s};
