/* ---------- T2: Pneumatik & Vakuumtechnik ---------- */
function sauger(o){const n=o.n||4,D=o.D||40,cw=10+D*.5,x0=70,x1=330;let s='';
 s+=`<rect x="${x0-14}" y="58" width="${x1-x0+28}" height="14" rx="3" fill="color-mix(in srgb,var(--mute) 55%,var(--card))" stroke="var(--ink)" stroke-width="2"/><rect x="${(x0+x1)/2-8}" y="22" width="16" height="36" fill="color-mix(in srgb,var(--mute) 55%,var(--card))" stroke="var(--ink)" stroke-width="2"/>`;
 for(let i=0;i<n;i++){const cx=n>1?x0+(x1-x0)*i/(n-1):(x0+x1)/2;s+=`<rect x="${cx-3}" y="72" width="6" height="22" fill="var(--ink)"/><path d="M${F(cx-cw/2)} 120L${F(cx-5)} 94H${F(cx+5)}L${F(cx+cw/2)} 120Z" fill="color-mix(in srgb,var(--flow) 30%,var(--card))" stroke="var(--ink)" stroke-width="2"/>`}
 s+=`<rect x="${x0-40}" y="120" width="${x1-x0+80}" height="14" fill="color-mix(in srgb,var(--mute) 35%,var(--card))" stroke="var(--ink)" stroke-width="2"/>`;
 return s}
const pnSkizze=k=>{let s=sauger({n:4,D:50});s+=KPF(446,118,70,true)+L(432,74,SUB('F_halt'),'end',17,'var(--flow)',700)+L(432,94,'Δp · A · n','end',13,'var(--ink)',600);
 s+=KPF(446,140,70,false,'var(--red)')+L(432,190,SUB('F_nötig'),'end',17,'var(--red)',700)+L(432,210,'m · (g + a) · S','end',13,'var(--ink)',600);
 s+=L(200,160,'Blech, m','middle',15,'var(--ink)',600)+L(70,40,'Unterdruck Δp im Sauger','start',14,'var(--ink)',600)+`<path d="M110 46L128 98" stroke="var(--ink)" stroke-width="1.2"/>`+L(200,250,'Die Haltekraft muss größer sein als die nötige Kraft','middle',14,'var(--mute)',500);return s};
