/* ---------- T2: Antriebe & Getriebe ---------- */
function antrieb(o){const i=o.i||16,r2=Math.min(48,14+Math.sqrt(i)*7),r1=12;let s='';
 s+=RC(30,96,110,78,'color-mix(in srgb,var(--flow) 22%,var(--card))','var(--ink)',8,2);for(let k=0;k<5;k++)s+=`<path d="M${44+k*18} 96V174" stroke="var(--ink)" stroke-width="1" opacity=".35"/>`;
 s+=L(85,140,'M','middle',22,'var(--ink)',800)+`<rect x="140" y="128" width="40" height="14" fill="color-mix(in srgb,var(--mute) 55%,var(--card))" stroke="var(--ink)" stroke-width="1.6"/><rect x="176" y="120" width="10" height="30" fill="var(--amber)" stroke="var(--ink)" stroke-width="1.6"/>`;
 s+=RC(186,70,140,130,'var(--card)','var(--ink)',8,2.2);
 const g=(cx,cy,r,z)=>{let p='';for(let j=0;j<z;j++){const a=j*2*Math.PI/z,b=a+Math.PI/z*.55;p+=`L${F(cx+(r+5)*Math.cos(a))} ${F(cy+(r+5)*Math.sin(a))}L${F(cx+(r+5)*Math.cos(b))} ${F(cy+(r+5)*Math.sin(b))}L${F(cx+r*Math.cos(b+.15))} ${F(cy+r*Math.sin(b+.15))}L${F(cx+r*Math.cos(a+2*Math.PI/z-.15))} ${F(cy+r*Math.sin(a+2*Math.PI/z-.15))}`}return `<path d="M${p.slice(1)}Z" fill="color-mix(in srgb,var(--mute) 45%,var(--card))" stroke="var(--ink)" stroke-width="1.4"/><circle cx="${cx}" cy="${cy}" r="4" fill="var(--ink)"/>`};
 s+=g(206+r1,135,r1,8)+g(206+2*r1+10+r2,135,r2,Math.max(10,Math.round(r2*.65)));
 s+=`<rect x="326" y="128" width="40" height="14" fill="color-mix(in srgb,var(--mute) 55%,var(--card))" stroke="var(--ink)" stroke-width="1.6"/>`+`<ellipse cx="400" cy="135" rx="34" ry="44" fill="color-mix(in srgb,var(--amber) 35%,var(--card))" stroke="var(--ink)" stroke-width="2"/>`;
 return s}
const grSkizze=k=>{let s=antrieb({i:16});s+=L(85,84,'Motor','middle',15,'var(--ink)',700)+L(256,62,'Getriebe i','middle',15,'var(--ink)',700)+L(400,82,'Trommel','middle',15,'var(--ink)',700);
 s+=L(85,206,SUB('n_an hoch'),'middle',15,'var(--red)',700)+L(85,226,SUB('M_an klein'),'middle',15,'var(--flow)',700)+L(400,206,SUB('n_ab = n_an ÷ i'),'middle',15,'var(--red)',700)+L(400,226,SUB('M_ab = M_an · i · η'),'middle',15,'var(--flow)',700);return s};
